import re
class Audit(HTMLParser):
 def __init__(self):
  super().__init__();self.ids=[];self.refs=[];self.stack=[];self.issues=[];self.h1=0;self.posts=0;self.projects=0
 def handle_starttag(self,t,a):
  d=dict(a)
  if 'id' in d:self.ids.append(d['id'])
  if t=='a' and d.get('href','').startswith('#') and len(d['href'])>1:self.refs.append(d['href'][1:])
  if 'aria-controls' in d:self.refs.append(d['aria-controls'])
  if t=='h1':self.h1+=1
  if d.get('class')=='post':self.posts+=1
  if d.get('class')=='project':self.projects+=1
  if t not in ['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','path','circle','rect','ellipse'] and t"'!='"'"'!doctype'"': self.stack.append(t)
 def handle_endtag(self,t):
  if t in ['path','circle','rect','ellipse']:return
  if not self.stack or self.stack[-1]"'!=t:self.issues.append(('"'mismatch',t,self.stack[-3:]));return
  self.stack.pop()
s=Path('index.html').read_text();a=Audit();a.feed(s)
assert len(a.ids)==len(set(a.ids)),'Duplicate ids'
assert all(x in a.ids for x in a.refs),'Broken fragment links'
assert a.h1==1 and a.posts==6 and a.projects==4
assert not a.issues,a.issues
assert not a.stack,a.stack
