 rgb=[int(h[i:i+2],16)/255 for i in (1,3,5)]
 v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in rgb]
 return sum(x*y for x,y in zip(v,[.2126,.7152,.0722]))
for name,fg,bg in [('light body','#454b43','#f7f6f0'),('light muted','#666b61','#f7f6f0'),('light accent','#a04d32','#f7f6f0'),('light tags','#666b61','#eceee4'),('dark body','#ced3c7','#1d2923'),('dark muted','#adb6a7','#25342b'),('dark tags','#adb6a7','#2c3b31')]:
 l=sorted([luminance(fg),luminance(bg)]);r=(l[1]+.05)/(l[0]+.05);assert r>=4.5,(name,r);print(name,'contrast',round(r,2))
