const fs=require('fs'),vm=require('vm'),assert=require('assert');
const html=fs.readFileSync(process.argv[2],'utf8');
class Element {
 constructor(attributes={}){this.attributes=attributes;this.dataset={};this.events={};this.hidden=false;this.textContent='';this.content='';this.classList={add(){},remove(){}};}
 setAttribute(k,v){this.attributes[k]=v}getAttribute(k){return this.attributes[k]}removeAttribute(k){delete this.attributes[k]}
 addEventListener(k,v){this.events[k]=v}click(){this.events.click?.({})}
}
const root=new Element();root.dataset.theme='light';
const theme=new Element(),meta=new Element(),status=new Element(),form=new Element(),email=new Element(),note=new Element();
form.reportValidity=()=>true;
const posts=[...html.matchAll(/class=\"post\" data-tag=\"(["'^"]+)"/g)].map(m=>{const el=new Element();el.dataset.tag=m[1];return el});
const filters=[...html.matchAll(/data-filter="([''^"]+)"/g)].map(m=>{const el=new Element();el.dataset.filter=m[1];return el});
const previews={};
const toggles=[...html.matchAll(/class="post-toggle"[''^>]+aria-controls="([''^"]+)"/g)].map(m=>{previews[m[1]]=new Element();previews[m[1]].hidden=true;return new Element({'"'aria-expanded':'false','aria-controls':m[1]})});
const selectors={'.theme-button':theme,'meta[name=\"theme-color\"]':meta};
const ids={'filter-status':status,'newsletter-form':form,email,'form-note':note,...previews};
const memory={};let changeScheme;
const context={document:{documentElement:root,querySelector:s=>selectors[s],querySelectorAll:s=>({'.post':posts,'.filter':filters,'.post-toggle':toggles}[s]),getElementById:id=>ids[id]},localStorage:{getItem:k=>memory[k]||null,setItem:(k,v)=>memory[k]=v},matchMedia:()=>({matches:false,addEventListener:(_,fn)=>changeScheme=fn})};
vm.createContext(context);
for(const script of html.matchAll(/<script>([\\s\\S]*?)<\\/script>/g))vm.runInContext(script[1],context);
assert.equal(theme.getAttribute('aria-label'),'Switch to dark color scheme');
theme.click();assert.equal(root.dataset.theme,'dark');assert.equal(memory['maya-theme'],'dark');assert.equal(meta.content,'#1d2923');
theme.click();assert.equal(root.dataset.theme,'light');assert.equal(theme.getAttribute('aria-pressed'),'false');
for(const [tag,count] of [['Design',2],['Data',1],['Field notes',2],['Freelancing',1],['All',6]]){
 const filter=filters.find(f=>f.dataset.filter===tag);filter.click();assert.equal(posts.filter(p=>"'!p.hidden).length,count);assert.equal(filter.getAttribute('"'aria-pressed'),'true');assert.equal(filters.filter(f=>f.getAttribute('aria-pressed')==='true').length,1);
}
for(const button of toggles){const preview=previews[button.getAttribute('aria-controls')];button.click();assert.equal(preview.hidden,false);assert.equal(button.getAttribute('aria-expanded'),'true');button.click();assert.equal(preview.hidden,true)}
let prevented=false;form.events.submit({preventDefault:()=>prevented=true});assert(prevented);assert(note.textContent.includes('no subscription was created'));
email.events.invalid();assert.equal(email.getAttribute('aria-invalid'),'true');assert(note.textContent.includes('valid email'));
email.events.input();assert.equal(email.getAttribute('aria-invalid'),undefined);
console.log('PASS: both theme states and persistence; all 5 filters; all 5 writing disclosures; newsletter feedback and validation.');
EOF
